parameters.jsCode:
// Format SW1 response for Router
const items = $input.all();
const aiOutput = items[0].json.output || items[0].json;
const inputData = $('When Executed by Another Workflow').first().json;

// If AI returned structured response, use it
if (aiOutput.workflow === 'SW1') {
  return [{
    json: aiOutput
  }];
}

// Otherwise, build structured response
let response = {
  workflow: 'SW1',
  operation: 'unknown',
  success: true,
  data: null,
  summary: '',
  error: null
};

// Try to parse AI output
if (typeof aiOutput === 'string') {
  try {
    const parsed = JSON.parse(aiOutput);
    response = { ...response, ...parsed };
  } catch (e) {
    response.summary = aiOutput;
  }
} else if (typeof aiOutput === 'object') {
  response = { ...response, ...aiOutput };
}

// Ensure we have operation type
if (inputData.ticket_id) {
  response.operation = 'get_ticket';
} else if (inputData.intent && inputData.intent.includes('workload')) {
  response.operation = 'analytics';
} else if (inputData.customer_email || inputData.query) {
  response.operation = 'search';
} else {
  response.operation = 'list_tickets';
}

return [{
  json: response
}];

// Log API call to Supabase
const items = $input.all();
const inputData = $('When Executed by Another Workflow').first().json;
const response = items[0].json;

// Build log entry
const logEntry = {
  workflow_id: 'SW1',
  run_id: $execution.id,
  node_name: 'SW1_AI_Agent',
  direction: 'response',
  method: response.operation || 'read',
  url: inputData.ticket_id 
    ? `https://ironsidecomputers.gorgias.com/api/tickets/${inputData.ticket_id}`
    : 'https://ironsidecomputers.gorgias.com/api/tickets',
  status_code: response.success ? 200 : 500,
  request_body: JSON.stringify({
    ticket_id: inputData.ticket_id,
    filters: inputData.filters,
    intent: inputData.intent
  }),
  response_body: JSON.stringify(response.data || response.summary),
  error_message: response.error || null,
  actor_user: inputData.user || null,
  channel: inputData.channel || null,
  thread_ts: inputData.thread_ts || null,
  ticket_id: inputData.ticket_id || null,
  tags: [],
  duration_ms: null,
  extra: JSON.stringify({
    operation: response.operation,
    intent: inputData.intent
  })
};

return [{
  json: logEntry
}];
